async function api<T=any>(path:string,body?:unknown):Promise<T>{let response:Response;try{response=await fetch(path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json','X-Hermo-CSRF':csrf},body:body===undefined?undefined:JSON.stringify(body),credentials:'same-origin'});}catch{throw new Error('Hermo lost its local connection. Keep the server running, then refresh and unlock the workspace.');}let data;try{data=await response.json();}catch{throw new Error('Hermo is unavailable. Check the local server.');}if(!response.ok)throw new ApiError(data.error?.message??'The request could not complete.',response.status,data.error?.code);return data;}
