function Logo({compact=false}:{compact?:boolean}){return <span className="brand"><img src="/brand/hermo-crab.png" alt="" width="31" height="31"/>{!compact&&<span>hermo</span>}</span>;}
function Button({children,icon:Icon,variant='primary',busy=false,...props}:React.ButtonHTMLAttributes<HTMLButtonElement>&{icon?:LucideIcon;variant?:'primary'|'secondary'|'ghost'|'danger';busy?:boolean}){return <button {...props} disabled={props.disabled||busy} aria-busy={busy||undefined} className={`button ${variant} ${props.className??''}`}>{busy?<Loader2 size={16} className="spin" aria-hidden="true"/>:Icon&&<Icon size={16} aria-hidden="true"/>}<span>{children}</span></button>;}
function Field({label,hint,error,...props}:React.InputHTMLAttributes<HTMLInputElement>&{label:string;hint?:string;error?:string}){const id=useId();return <label className="field" htmlFor={id}><span>{label}</span><input {...props} id={id} aria-label={props['aria-label']??label} aria-invalid={error?true:props['aria-invalid']} aria-describedby={[props['aria-describedby'],hint?id+'-hint':undefined,error?id+'-error':undefined].filter(Boolean).join(' ')||undefined}/>{hint&&<small id={id+'-hint'}>{hint}</small>}{error&&<small id={id+'-error'} role="alert">{error}</small>}</label>;}
function Pill({status}:{status:string}){const good=['connected','succeeded','published'].includes(status),bad=['failed','expired','timed_out'].includes(status),active=['running','queued','preparing','awaiting_approval','verifying'].includes(status);return <span className={`pill ${good?'good':bad?'bad':active?'blue':'quiet'}`}><span className={active?'pulse':''}/>{({auth_required:'Needs sign-in',needs_confirmation:'Connect tab',tab_offline:'Tab offline',succeeded:'Verified',published:'Live',connected:'Connected',stopped:'Stopped'} as Record<string,string>)[status]??status.replaceAll('_',' ')}</span>;}
function Empty({icon:Icon,title,detail,action}:{icon:LucideIcon;title:string;detail:string;action?:React.ReactNode}){return <div className="empty"><span className="empty-icon"><Icon size={24}/></span><h3>{title}</h3><p>{detail}</p>{action}</div>;}
function Modal({title,description,children,onClose,wide=false,alert=false}:{title:string;description:string;children:React.ReactNode;onClose:()=>void;wide?:boolean;alert?:boolean}){const returnFocus=useRef(document.activeElement as HTMLElement|null);return <Dialog.Root open onOpenChange={open=>{if(!open)onClose();}}><Dialog.Portal><Dialog.Overlay className="dialog-overlay"/><Dialog.Content onCloseAutoFocus={event=>{event.preventDefault();if(returnFocus.current?.isConnected)returnFocus.current.focus({preventScroll:true});else document.getElementById('workspace-content')?.focus({preventScroll:true});}} role={alert?'alertdialog':'dialog'} className={`dialog-content ${wide?'wide':''}`}><div className="dialog-heading"><div><Dialog.Title>{title}</Dialog.Title><Dialog.Description>{description}</Dialog.Description></div><Dialog.Close asChild><button className="icon-button" aria-label="Close dialog"><X size={20} aria-hidden="true"/></button></Dialog.Close></div>{children}</Dialog.Content></Dialog.Portal></Dialog.Root>;}
