function download(value:unknown,name:string){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function copy(value:string){await navigator.clipboard.writeText(value);}
function CopyButton({value}:{value:string}){const[copied,setCopied]=useState(false);const[error,setError]=useState(false);return <button className="copy-button" aria-label={copied?'Copied':'Copy to clipboard'} onClick={async()=>{try{await copy(value);setCopied(true);setError(false);setTimeout(()=>setCopied(false),2000);}catch{setError(true);}}}>{copied?<Check size={15}/>:<Copy size={15}/>}<span>{error?'Select and copy':copied?'Copied':'Copy'}</span></button>;}
